<?php
require_once __DIR__.'/../bootstrap/app.php';require_role('SUPER_ADMIN');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$uid=(int)($_POST['user_id']??0);$action=$_POST['action']??'';$reason=trim($_POST['reason']??'');try{transaction(function()use($uid,$action,$reason){$app=db_one("SELECT u.*,t.Name FROM USER_ACCOUNT u JOIN TRAINER t ON t.TrainerID=u.TrainerID WHERE u.UserID=? AND u.Role='TRAINER' FOR UPDATE",'i',[$uid]);if(!$app)throw new RuntimeException('Trainer application not found.');if($action==='approve'){db_execute("UPDATE USER_ACCOUNT SET Status='ACTIVE',RejectedAt=NULL,RejectionReason=NULL WHERE UserID=?",'i',[$uid]);db_execute("UPDATE TRAINER SET ApplicationStatus='APPROVED',RejectionReason=NULL WHERE TrainerID=?",'i',[$app['TrainerID']]);notify_users([$uid],'Trainer application approved','Your account is active. You can now create classes.','SUCCESS');}elseif(in_array($action,['reject','more_info'],true)){if($reason==='')throw new RuntimeException('A reason is required.');$status=$action==='reject'?'REJECTED':'NEEDS_INFORMATION';db_execute('UPDATE USER_ACCOUNT SET Status=?,RejectedAt=CASE WHEN ?="REJECTED" THEN NOW() ELSE NULL END,RejectionReason=? WHERE UserID=?','sssi',[$status,$status,$reason,$uid]);db_execute('UPDATE TRAINER SET ApplicationStatus=?,RejectionReason=? WHERE TrainerID=?','ssi',[$status,$reason,$app['TrainerID']]);notify_users([$uid],$action==='reject'?'Trainer application rejected':'More information required',$reason,'WARNING');}else throw new RuntimeException('Invalid action.');audit('trainer.application_'.$action,'TRAINER',(int)$app['TrainerID'],['reason'=>$reason]);});set_flash('success','Application updated.');redirect('admin/trainers.php');}catch(Throwable $e){$errors[]=$e->getMessage();}}
$apps=db_all("SELECT u.*,t.Name,t.PhoneNo,t.Experience,t.Specialization,t.ApplicationStatus,(SELECT DocumentID FROM TRAINER_DOCUMENT d WHERE d.TrainerID=t.TrainerID ORDER BY d.DocumentID DESC LIMIT 1) DocumentID FROM USER_ACCOUNT u JOIN TRAINER t ON t.TrainerID=u.TrainerID WHERE u.Role='TRAINER' ORDER BY FIELD(u.Status,'PENDING_APPROVAL','NEEDS_INFORMATION','ACTIVE','REJECTED'),u.CreatedAt DESC");$pageTitle='Trainer applications';$pageSubtitle='Review identities, qualifications, and access';include ROOT_PATH.'/includes/header.php';?>
<?php if($errors):?><div class="alert alert-danger" role="alert"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="table-wrap"><table class="data-table"><caption class="sr-only">Trainer applications</caption><thead><tr><th scope="col">Trainer</th><th scope="col">Specialization</th><th scope="col">Experience</th><th scope="col">Status</th><th scope="col">Document</th><th scope="col">Decision</th></tr></thead><tbody><?php foreach($apps as $a):?><tr><td><strong><?=e($a['Name'])?></strong><br><small><?=e($a['Email'])?> · <?=e($a['PhoneNo'])?></small></td><td><?=e($a['Specialization'])?></td><td><?=(int)$a['Experience']?> years</td><td><span class="badge <?=in_array($a['Status'],['ACTIVE'],true)?'badge-green':($a['Status']==='REJECTED'?'badge-red':'badge-amber')?>"><?=e($a['Status'])?></span></td><td><?=$a['DocumentID']?'<a class="btn btn-ghost btn-sm" href="trainer-document.php?id='.(int)$a['DocumentID'].'">View</a>':'—'?></td><td><?php if(in_array($a['Status'],['PENDING_APPROVAL','NEEDS_INFORMATION'],true)):?><form method="post" class="inline-decision"><?=csrf_field()?><input type="hidden" name="user_id" value="<?=$a['UserID']?>"><input name="reason" aria-label="Decision reason" placeholder="Reason for reject/info"><button class="btn btn-success btn-sm" name="action" value="approve">Approve</button><button class="btn btn-ghost btn-sm" name="action" value="more_info">More info</button><button class="btn btn-danger btn-sm" name="action" value="reject">Reject</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php include ROOT_PATH.'/includes/footer.php';?>
